const body = ($input.first().json.body || {});
const v = (body.embedding || {}).values;
if (!v) throw new Error('немає вектора запиту');
const pb = {"key": "metadata.source", "match": {"value": "playbook"}};
return [{ json: { search: { searches: [
  { vector: v, limit: 3, with_payload: true, filter: { must_not: [pb] } },
  { vector: v, limit: 3, with_payload: true, filter: { must: [pb] } } ] } } }];

if (!$('Code: Prepare').first().json.ok) return [{ json: { ok: false, error: 'запит надто короткий' } }];
const b = $input.first().json.body || {};
if (!Array.isArray(b.result) || b.result.length < 2) return [{ json: { ok: false, error: 'пошук недоступний' } }];
const pick = r => { const m = (r.payload || {}).metadata || {}; return { ticket: m.ticket, score: r.score, text: String(r.payload.content || '').slice(0, 900) }; };
return [{ json: { ok: true, results: (b.result[0] || []).map(pick), approved_playbooks: (b.result[1] || []).map(pick) } }];
